        // Mock window.open
        mockWindow = {
            close: vi.fn(),
            closed: false,
            window: {closed: false},
        } as unknown as Window;

        window.open = vi.fn().mockReturnValue(mockWindow);

        // Clear storage
        sessionStorage.clear();
        localStorage.clear();
    })

afterEach(() => {
        vi.restoreAllMocks();
        vi.unstubAllGlobals();
        window.open = originalOpen;
        MockBroadcastChannel.reset();
