beforeEach(() => {
    workspaceDir = mkdtempSync(join(tmpdir(), "dbt-install-"));
    // Mirror the runtime venv interpreter layout (Scripts/python.exe on Windows).
    venvPython =
      process.platform === "win32"
        ? join(workspaceDir, ".venv", "Scripts", "python.exe")
        : join(workspaceDir, ".venv", "bin", "python");
    runCommands = [];
    configUpdates = [];

    // Quick-picks: dbt version then adapter.
    const picks = [{ label: "1.9" }, { label: "duckdb" }];
    (window as any).showQuickPick = jest.fn(() =>
      Promise.resolve(picks.shift()),
    );
    // Choose "Create virtual environment" at the remediation prompt.
    (window as any).showErrorMessage = jest.fn(() =>
      Promise.resolve("Create virtual environment"),
    );
    (window as any).showInformationMessage = jest.fn(() => Promise.resolve());

    (workspace as any).workspaceFolders = [
      { uri: { fsPath: workspaceDir }, name: "proj", index: 0 },
    ];
    (workspace as any).getConfiguration = jest.fn(() => ({
      get: jest.fn((_k: string, d: unknown) => d),
      has: jest.fn(),
      update: jest.fn((key: string, value: unknown) => {
        configUpdates.push({ key, value });
        return Promise.resolve();
      }),
    }));

    // Fake command factory mimicking a Homebrew externally-managed interpreter.
    const commandProcessExecutionFactory = {
      createCommandProcessExecution: ({
        command,
        args,
      }: {
        command: string;
        args: string[];
      }) => ({
        completeWithTerminalOutput: async () => {
          runCommands.push({ command, args });
          if (args.includes("venv")) {
            // Materialize the venv interpreter so existsSync() sees it.
            mkdirSync(dirname(venvPython), { recursive: true });
            writeFileSync(venvPython, "");
            return { stdout: "", stderr: "", fullOutput: "" };
          }
          if (args.includes("pip")) {
            if (command === brewPython) {
              const err =
                "error: externally-managed-environment\n" +
                "× This environment is externally managed";
              return { stdout: "", stderr: err, fullOutput: err };
            }
            const ok = "Successfully installed dbt-core dbt-duckdb";
            return { stdout: ok, stderr: "", fullOutput: ok };
          }
          return { stdout: "", stderr: "", fullOutput: "" };
        },
      }),
    };

    const pythonEnvironment = {
      pythonPath: brewPython,
      pythonVersion: "3.12.0",
      getEnvironmentVariables: () => ({}),
    };
    dbtProjectContainer = {
      detectDBT: jest.fn(() => Promise.resolve()),
      initialize: jest.fn(),
    };
    const telemetry = {
      sendTelemetryEvent: jest.fn(),
      sendTelemetryError: jest.fn(),
    };

    commands = new (WalkthroughCommands as any)(
      dbtProjectContainer,
      telemetry,
      commandProcessExecutionFactory,
      pythonEnvironment,
      { debug: jest.fn(), error: jest.fn() },
    );
  })

afterEach(() => {
    rmSync(workspaceDir, { recursive: true, force: true });
    (window as any).showQuickPick = orig.showQuickPick;
    (window as any).showErrorMessage = orig.showErrorMessage;
    (window as any).showInformationMessage = orig.showInformationMessage;
    (workspace as any).getConfiguration = orig.getConfiguration;
    (workspace as any).workspaceFolders = orig.workspaceFolders;
    jest.clearAllMocks();
  })

beforeEach(() => {
    resolveSqlFmtPath = jest.fn();
    invalidateSqlFmtPathCache = jest.fn();
    getProjects = jest.fn().mockReturnValue([{ projectRoot: "/p" }]);
    getFromGlobalState = jest.fn().mockReturnValue(undefined);
    setToGlobalState = jest.fn();
    showInformationMessage = jest.fn();
    showErrorMessage = jest.fn();
    sendTelemetryEvent = jest.fn();
    sendTelemetryError = jest.fn();
    onManifestChanged = jest.fn((cb: () => unknown) => {
      onManifestChangedListener = cb;
      return { dispose: jest.fn() };
    });
    completeWithTerminalOutput = jest.fn();
    completeWithTerminalOutput.mockResolvedValue({
      stdout: "Successfully installed shandy-sqlfmt-0.21.0",
      stderr: "",
    });
    createCommandProcessExecution = jest.fn();
    createCommandProcessExecution.mockReturnValue({
      completeWithTerminalOutput,
    });
    // withProgress just invokes the task and returns its result, matching the
    // real signature closely enough for our purposes.
    withProgress = jest.fn();
    withProgress.mockImplementation(
      async (_opts: unknown, task: () => Promise<unknown>) => task(),
    );

    onManifestChangedListener = undefined;
    onDidChangeActiveTextEditorListener = undefined;
    const win = vscode.window as unknown as Record<string, unknown>;
    win.activeTextEditor = undefined;
    win.showInformationMessage = showInformationMessage;
    win.showErrorMessage = showErrorMessage;
    win.withProgress = withProgress;
    win.onDidChangeActiveTextEditor = jest.fn(
      (cb: (editor: vscode.TextEditor | undefined) => unknown) => {
        onDidChangeActiveTextEditorListener = cb;
        return { dispose: jest.fn() };
      },
    );
    // `getFirstWorkspacePath()` (used by the install spawn) reads
    // `workspace.workspaceFolders[0].uri.fsPath`. Provide a folder so the
    // install path doesn't crash before reaching pip.
    (vscode.workspace as unknown as Record<string, unknown>).workspaceFolders =
      [{ uri: { fsPath: "/workspace" } }];
  })

afterEach(() => {
    jest.clearAllMocks();
    const win = vscode.window as unknown as Record<string, unknown>;
    delete win.activeTextEditor;
    delete win.onDidChangeActiveTextEditor;
    delete win.withProgress;
    delete (vscode.workspace as unknown as Record<string, unknown>)
      .workspaceFolders;
  })

