beforeAll(async () => {
    evaluator = createSkillEvaluator('jank_frame_detail');
    await evaluator.loadTrace(getTestTracePath(TRACE_FILE));

    // Query to find a janky frame to use for testing
    // This gives us real timestamps from the trace
    const frameQuery = await evaluator.executeSQL(`
      SELECT
        printf('%d', ts) as start_ts,
        printf('%d', ts + dur) as end_ts,
        ROUND(dur / 1e6, 2) as dur_ms,
        jank_type,
        layer_name
      FROM actual_frame_timeline_slice
      WHERE jank_type != 'None'
        AND surface_frame_token IS NOT NULL
        AND dur > 16000000
      ORDER BY dur DESC
      LIMIT 1
    `);

    if (!frameQuery.error && frameQuery.rows.length > 0) {
      const row = frameQuery.rows[0];
      // Extract package from layer_name (e.g., "com.example.app/MainActivity#0" -> "com.example.app")
      const layerName = row[4] as string || '';
      const packageMatch = layerName.match(/^([^/]+)/);
      const packageName = packageMatch ? packageMatch[1] : '';

      testFrameParams = {
        start_ts: row[0] as string,
        end_ts: row[1] as string,
        package: packageName,
        dur_ms: row[2] as number,
        jank_type: row[3] as string,
      };
      console.log(`[Test Setup] Found janky frame: ${testFrameParams.dur_ms}ms, type: ${testFrameParams.jank_type}`);
    } else {
      console.warn('[Test Warning] No janky frames found in trace. Some tests will use fallback timestamps.');
    }
  }, 60000)

afterAll(async () => {
    await evaluator.cleanup();
    // Wait for trace processor port release
    await new Promise(resolve => setTimeout(resolve, 2500));
  })

beforeAll(async () => {
    evaluator = createSkillEvaluator('memory_analysis');
    await evaluator.loadTrace(getTestTracePath(TRACE_FILE));

    // Check if trace has any process we can analyze
    try {
      const processResult = await evaluator.executeSQL(`
        SELECT name FROM process
        WHERE name IS NOT NULL AND name != ''
        ORDER BY pid DESC
        LIMIT 1
      `);
      if (!processResult.error && processResult.rows.length > 0) {
        targetProcessName = processResult.rows[0][0] as string;
      }
    } catch (e) {
      // Ignore
    }

    // Check if trace has GC events
    try {
      const result = await evaluator.executeSQL(`
        SELECT COUNT(*) as count
        FROM slice s
        JOIN thread_track tt ON s.track_id = tt.id
        JOIN thread t ON tt.utid = t.utid
        WHERE s.name GLOB '*GC*' OR s.name GLOB '*gc*' OR s.name GLOB '*ConcurrentCopying*'
        LIMIT 1
      `);
      hasGCData = !result.error && result.rows.length > 0 && (result.rows[0][0] as number) > 0;
    } catch (e) {
      hasGCData = false;
    }

    // Check if trace has FrameTimeline data (for GC-frame impact analysis)
    try {
      const result = await evaluator.executeSQL(`
        SELECT COUNT(*) as count
        FROM actual_frame_timeline_slice
        WHERE surface_frame_token IS NOT NULL
        LIMIT 1
      `);
      hasFrameTimelineData = !result.error && result.rows.length > 0 && (result.rows[0][0] as number) > 0;
    } catch (e) {
      hasFrameTimelineData = false;
    }

    if (!hasGCData) {
      console.warn(`[Test Warning] Trace ${TRACE_FILE} does not have GC data. Tests will handle empty results gracefully.`);
    }
    if (!hasFrameTimelineData) {
      console.warn(`[Test Warning] Trace ${TRACE_FILE} does not have FrameTimeline data. GC-frame impact tests may have limited data.`);
    }
  }, 60000)

afterAll(async () => {
    await evaluator.cleanup();
    // Wait for trace processor port release (destroy() has a 2s setTimeout)
    await new Promise(resolve => setTimeout(resolve, 2500));
  })

