        activeSocket = sock;
        if (socketReadyResolve) socketReadyResolve();
        sock.on("message", (raw) => {
          const text =
            typeof raw === "string"
              ? raw
              : Buffer.isBuffer(raw)
                ? raw.toString("utf8")
                : Buffer.from(raw as ArrayBuffer).toString("utf8");
          try {
            observedTypes.push(String(JSON.parse(text).type ?? ""));
          } catch {
            /* ignore non-JSON */
          }
        });
      });
      http.listen(0, "127.0.0.1", doneStart);
    }),
)

