before(async () => {
  srv = await new Promise<ServerState>((resolve) => {
    let llmCalls = 0;
    let turnGenCalls = 0;
    let nextVerdict: "PASS" | "FAIL" = "PASS";
    const server = createServer((req, res) => {
      let body = "";
      req.on("data", (c: Buffer) => (body += c.toString()));
      req.on("end", () => {
        if ((req.url ?? "").startsWith("/v1/chat/completions")) {
          llmCalls++;
          res.writeHead(200, { "Content-Type": "application/json" });
          // One endpoint backs both the attacker turn generator and the judge;
          // route by the attacker prompt's unique marker.
          if (body.includes(TURN_GEN_MARKER)) {
            turnGenCalls++;
            res.end(turnGenJson());
          } else {
            res.end(judgeJson(nextVerdict));
          }
          return;
        }
        res.writeHead(404);
        res.end("no");
      });
    });
    server.listen(0, "127.0.0.1", () => {
      const { port } = server.address() as { port: number };
      resolve({
        server,
        port,
        get llmCalls() {
          return llmCalls;
        },
        get turnGenCalls() {
          return turnGenCalls;
        },
        get nextVerdict() {
          return nextVerdict;
        },
        set nextVerdict(v) {
          nextVerdict = v;
        },
        reset(v) {
          llmCalls = 0;
          turnGenCalls = 0;
          nextVerdict = v;
        },
      });
    });
  });
})

after(async () => {
  await new Promise<void>((resolve, reject) =>
    srv.server.close((e) => (e ? reject(e) : resolve()))
  );
})

