          field: "soulMd",
          content,
          version: i,
          changeSource: i === 1 ? "system" : "self_edit",
          contentHash: sha256(content),
        });
      }

      // Create 2 versions for identityMd
      for (let i = 1; i <= 2; i++) {
        const content = `identity version ${i}`;
        createContextVersion({
          agentId: historyAgentId,
          field: "identityMd",
          content,
          version: i,
          changeSource: "api",
          contentHash: sha256(content),
        });
      }
    })

