				data: {
					item: {
						id: "rev_draft",
						collection: "posts",
						entryId: "post_1",
						data: { title: "Draft Title" },
						authorId: null,
						createdAt: "2025-01-01T00:00:00Z",
					},
				},
			})
			// Publishing succeeds; the server has now promoted the draft to live.
			.on("POST", "/_emdash/api/content/posts/post_1/publish", {
				data: { item: publishedNoChanges() },
			});
	})

