beforeEach(() => {
      originalEnv = { ...process.env }
      // Clear all safety-related env vars using delete for proper removal
      // Type assertion needed because TypeScript declares process.env as readonly
      const env = process.env as Record<string, string | undefined>
      delete env.NODE_ENV
      delete env.VERCEL
      delete env.CI
      delete env.DANGEROUSLY_ALLOW_REMOTE_DB
    })

afterEach(() => {
      // Restore original env
      // Type assertion needed because TypeScript declares process.env as readonly
      const env = process.env as Record<string, string | undefined>
      Object.keys(env).forEach((key) => {
        delete env[key]
      })
      Object.entries(originalEnv).forEach(([key, value]) => {
        if (value !== undefined) {
          env[key] = value
        }
      })
    })

beforeEach(() => {
      originalLifecycleEvent = process.env.npm_lifecycle_event
      delete (process.env as Record<string, string | undefined>)
        .npm_lifecycle_event
    })

afterEach(() => {
      const env = process.env as Record<string, string | undefined>
      if (originalLifecycleEvent !== undefined) {
        env.npm_lifecycle_event = originalLifecycleEvent
      } else {
        delete env.npm_lifecycle_event
      }
    })

afterEach(() => {
      const env = process.env as Record<string, string | undefined>
      if (originalNodeEnv !== undefined) {
        env.NODE_ENV = originalNodeEnv
      } else {
        delete env.NODE_ENV
      }
      if (originalLifecycleEvent !== undefined) {
        env.npm_lifecycle_event = originalLifecycleEvent
      } else {
        delete env.npm_lifecycle_event
      }
    })

