                    active: true,
                  },
                ],
                products: [
                  {
                    product: {
                      name: 'Pro Plan',
                      slug: 'pro-plan',
                      description: 'Professional tier',
                      active: true,
                      default: false,
                    },
                    price: {
                      type: PriceType.Subscription,
                      name: 'Monthly Pro',
                      slug: 'pro-monthly',
