      pricingModelId: pmId,
      pricingModelUpdatedAt: pmUpdatedAt,
    } = (
      await adminTransaction(
        async (ctx) => {
          const { organization } = await setupOrg({
            skipPricingModel: true,
          })

          // Create a pricing model using setupPricingModelTransaction
          const setupResult = await setupPricingModelTransaction(
            {
              input: {
                name: 'Test Export PM',
                isDefault: false,
                features: [],
                products: [
                  {
                    product: {
                      name: 'Test Product',
                      slug: 'test-product',
                      default: false,
                      active: true,
                    },
                    price: {
                      type: PriceType.Subscription,
                      unitPrice: 1000,
                      intervalUnit: IntervalUnit.Month,
                      intervalCount: 1,
                      isDefault: true,
                      active: true,
                      slug: 'test-price',
                    },
                    features: [],
                  },
                ],
                usageMeters: [],
                resources: [],
              },
              organizationId: organization.id,
              livemode: false,
            },
            ctx
          )

          const pm = setupResult.unwrap().pricingModel

          return Result.ok({
            pricingModelId: pm.id,
            pricingModelUpdatedAt: pm.updatedAt,
          })
        },
        { livemode: false }
      )
    ).unwrap()

    pricingModelId = pmId
    pricingModelUpdatedAt = pmUpdatedAt
  })

