    const insert = raw.prepare('INSERT INTO message (id, sender_id, ts, type, content) VALUES (?, ?, ?, ?, ?)')
    // Alice 文字消息 长度 3 / 6 / 40
    insert.run(1, 1, TS, 0, 'a'.repeat(3))
