        mockExecFile(cmd, args)
          .then((res: any) => cb(null, res.stdout, res.stderr))
          .catch((err: any) => cb(err));
      },
    }));
    vi.doMock("node:util", () => ({
      promisify:
        (fn: any) =>
        (...args: any[]) =>
          new Promise((resolve, reject) => {
            fn(...args, (err: any, ...results: any[]) => {
              if (err) reject(err);
              else resolve(results.length <= 1 ? results[0] : results);
            });
          }),
    }));
  })

