				return 'worktree /test/repo\nHEAD abc123\nbranch refs/heads/main\n';
			}
			if (command.includes('git worktree add')) {
				return '';
			}
			if (command.includes('git rev-parse --verify')) {
				throw new Error('Branch not found');
			}
			return '';
		});
	})

