beforeAll(async () => {
  orm = await MikroORM.init({
    metadataProvider: ReflectMetadataProvider,
    dbName: ':memory:',
    entities: [Author, Book, Publisher],
  });
  await orm.schema.create();

  const em = orm.em.fork();
  const authors = [
    new Author({ id: 1, name: 'a' }),
    new Author({ id: 2, name: 'b' }),
    new Author({ id: 3, name: 'c' }),
  ];
  em.persist(authors);

  const publishers = [new Publisher({ id: 1, name: 'AAA' }), new Publisher({ id: 2, name: 'BBB' })];
  em.persist(publishers);

  const books = [
    new Book({ id: 1, title: 'One', author: authors[0] }),
    new Book({ id: 2, title: 'Two', author: authors[0] }),
    new Book({ id: 3, title: 'Three', author: authors[1] }),
    new Book({ id: 4, title: 'Four', author: authors[2] }),
    new Book({ id: 5, title: 'Five', author: authors[2] }),
    new Book({ id: 6, title: 'Six', author: authors[2] }),
    new Book({ id: 7, title: 'Draft', author: authors[2], published: false }),
  ];
  books[0].publisher = ref(publishers[0]);
  books[1].publisher = ref(publishers[1]);
  books[2].publisher = ref(publishers[1]);
  books[3].publisher = ref(publishers[1]);
  books[4].publisher = ref(publishers[1]);
  books[5].publisher = ref(publishers[1]);
  em.persist(books);

  await em.flush();
})

beforeAll(async () => {
    orm = await initORMMongo();

    // Create 3 authors, each with 5 books; 4 shared tags, each tagged on several books
    const em = orm.em.fork();
    const tags = ['alpha', 'beta', 'gamma', 'delta'].map(name => em.create(BookTag, { name }));

    for (let a = 1; a <= 3; a++) {
      const author = em.create(Author, {
        name: `Author ${a}`,
        email: `author${a}@test.com`,
      });

      for (let b = 1; b <= 5; b++) {
        const book = em.create(Book, {
          title: `Book ${b} by Author ${a}`,
          author,
        });
        // Each book gets all 4 tags so limit=2 visibly truncates.
        tags.forEach(t => book.tags.add(t));
      }
    }

    await em.flush();
    em.clear();
  })

beforeAll(async () => {
    orm = await MikroORM.init({
      entities: [User, Post, Comment, Tag],
      dbName: ':memory:',
      metadataProvider: ReflectMetadataProvider,
    });
    await orm.schema.refresh();

    // Create 3 users, each with 5 posts
    const em = orm.em.fork();
    const tag1 = em.create(Tag, { name: 'tech' });
    const tag2 = em.create(Tag, { name: 'science' });

    let postIdx = 0;
    let commentIdx = 0;

    for (let u = 1; u <= 3; u++) {
      const user = em.create(User, { name: `User ${u}` });

      for (let p = 1; p <= 5; p++) {
        postIdx++;
        const post = em.create(Post, {
          title: `Post ${p} by User ${u}`,
          createdAt: new Date(2024, 0, postIdx), // Jan 1, Jan 2, ... Jan 15
          user: ref(user),
        });
        post.tags.add(p % 2 === 0 ? tag1 : tag2);

        // Each post gets 3 comments
        for (let c = 1; c <= 3; c++) {
          commentIdx++;
          em.create(Comment, {
            text: `Comment ${c} on Post ${p} by User ${u}`,
            createdAt: new Date(2024, 1, commentIdx), // Feb 1, Feb 2, ...
            post: ref(post),
          });
        }
      }
    }

    await em.flush();
  })

