beforeEach(() => {
    rafCallbacks = []
    nextRafId = 1
    cancelledIds = []
    global.requestAnimationFrame = ((cb: FrameRequestCallback) => {
      const id = nextRafId++
      rafCallbacks.push({ id, cb })
      return id
    }) as any
    global.cancelAnimationFrame = ((id: number) => {
      cancelledIds.push(id)
      rafCallbacks = rafCallbacks.filter((entry) => entry.id !== id)
    }) as any
  })

