            // Verify an ACK was sent back through the transferred port
            ackReceived = await new Promise<boolean>(resolve => {
                const timer = setTimeout(() => resolve(false), 500);
                hostPort.addEventListener("message", (event: MessageEvent) => {
                    if (isAck(event.data)) {
                        clearTimeout(timer);
                        resolve(true);
                    }
                });
                hostPort.start();
            });
        })

