    await globalThis.services.db
      .delete(storageVersions)
      .where(eq(storageVersions.storageId, testArtifactId));

    await globalThis.services.db
      .delete(storages)
      .where(eq(storages.id, testArtifactId));

    await globalThis.services.db
      .delete(scopes)
      .where(eq(scopes.id, testScopeId));
  })

