beforeAll(async () => {
  if (existsSync(FIX)) {
    content = await readFile(FIX, 'utf8');
  } else {
    try {
      const res = await fetch(URL);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      content = await res.text();
      await mkdir(FIX_DIR, { recursive: true });
      await writeFile(FIX, content, 'utf8');
    } catch (e) {
      console.warn(`[bidi bunched] SKIPPED — could not load ${URL}: ${(e as Error).message}`);
      content = null;
    }
  }
}, 60_000)

beforeAll(async () => {
  if (existsSync(FIX)) {
    content = await readFile(FIX, 'utf8');
    return;
  }
  try {
    const res = await fetch(URL);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    content = await res.text();
    await mkdir(FIX_DIR, { recursive: true });
    await writeFile(FIX, content, 'utf8');
  } catch (e) {
    console.warn(`[bidi conformance] SKIPPED — could not load ${URL}: ${(e as Error).message}`);
    content = null;
  }
}, 60_000)

