    vi.stubGlobal('fetch', (input: RequestInfo | URL, init?: RequestInit) => {
      const path =
        typeof input === 'string'
          ? input
          : input instanceof URL
            ? input.pathname + input.search
            : (input as Request).url;
      return backend.handleRequest(path, init);
    });
